import json, os, sys

base = "/Users/kristinarash/Library/Caches/sportsci-batch-98"
inputs = {p["id"]: p for p in json.load(open(os.path.join(base, "inputs.json"), encoding="utf-8"))}
for pid in ["Q89", "Q90", "Q91", "Q92", "Q93", "Q94", "Q95", "Q96"]:
    path = os.path.join(base, "drafts", pid + ".json")
    try:
        d = json.load(open(path, encoding="utf-8"))
    except Exception as e:
        print(pid, "JSON ERROR", e)
        continue
    src_ok = d.get("sourceFile") == inputs[pid]["sourceFile"]
    em = any("—" in json.dumps(v, ensure_ascii=False) for v in d.values() if isinstance(v, str))
    if d.get("paper"):
        em = em or "—" in json.dumps(d["paper"], ensure_ascii=False)
    print(pid, d.get("decision"), "sourceFile match:", src_ok, "em-dash:", em, "id ok:", d.get("id") == pid)
    if not src_ok:
        print("  draft :", repr(d.get("sourceFile")))
        print("  input :", repr(inputs[pid]["sourceFile"]))

